
<?php      class NewsScript  {   var $maxLength,    $lim,       $template,      $db_name,      $db_host,    $db_user,    $db_password,    $connection;         function NewsScript()   {       require('config.news.php');        $this->db_host = $db_host;    $this->db_name = $db_name;    $this->db_user = $db_user;    $this->db_password = $db_password;    $this->lim = $lim;    $this->template = $template;   }         function displayAll()   {               $result = mysql_query("SELECT * FROM newstbl ORDER BY date DESC LIMIT 0, $this->lim");            while($row = mysql_fetch_assoc($result))    {         $id = $row['id'];     $author =  $row['author'];     $content = $row['content'];     $date = $this->convertDate($row['date']);               require($this->template);         }           }         function displayItem($id)   {    if(is_numeric($id))    {         $result = mysql_query("SELECT * FROM newstbl WHERE id = '$id'");     $row = mysql_fetch_assoc($result);          $author =  $row['author'];     $content = $row['content'];     $date = $this->convertDate($row['date']);          require($this->template);               return true;    }    else return false;       }         function addNews($author, $content)   {               $sql = sprintf("INSERT INTO newstbl (author, content ,date) VALUES ('%s','%s',CURDATE())",               $this->clean($author), $this->clean($content));            $result = mysql_query($sql);               if($result)    {     return true;    }    else return false;   }         function deleteNews($id)   {       if(is_numeric($id))    {          $result = mysql_query("DELETE FROM newstbl WHERE id='$id'");                        if($result)     {      return true;    }     else return false;                 }    else return false;     }         function updateNews($id, $author, $content)   {    if(is_numeric($id))    {               $sql = sprintf("UPDATE newstbl SET author='%s', content='%s' WHERE id='%d'",     $this->clean($author), $this->clean($content), $id);          $result = mysql_query($sql);                        if($result)     {      return true;    }     else return false;   }    return false;   }                          function convertDate($date)   {    $date_array = explode("-",$date);    $y = $date_array[0];          $m = $date_array[1];          $d = $date_array[2];                    return $d . "/" . $m . "/" . $y;   }         function clean($str)   {       if(get_magic_quotes_gpc())    {     $str = stripslashes($str);    }       $str = mysql_real_escape_string($str);        return $str;   }         function addSmiley($msg)   {       $new_msg = str_replace(":)",'<img src="smileys/smiley1.gif">', $msg);    return $new_msg;    }  }    ?>